cd /workspace && LD_LIBRARY_PATH=/workspace/native PYTHONPATH=/workspace/.deps python3 -c "
import sys; sys.path.insert(0,'/workspace'); sys.path.insert(0,'/workspace/submission')
import verify
text = open('/tmp/hard1.json').read(); out = open('/tmp/hard1out.json').read()
try:
    verify.check(text, out); print('verify ok', len(out))
except verify.Bad as e: print('FAIL', e)
" ; python3 -c "
import sys, json; sys.path.insert(0,'/workspace/submission')
import hard_stress
from protocol import loads, validate
cases = []
for mode in ['route','admit']:
    for nw in [1,2,8]:
        for cm in ['tiny','small']:
            cases.append(hard_stress.build(3, mode, nw, cm))
for i in range(0, len(cases), 5):
    chunk = cases[i:i+5]
    t = json.dumps({'cases': chunk}, separators=(',',':'))
    try:
        validate(loads(t))
        open('/tmp/hard_%d.json'%(i//5),'w').write(t)
        print('chunk', i//5, 'ok', len(t))
    except Exception as e:
        print('chunk', i//5, 'invalid', e)
"
